create function private.master_admin_cost_authorized() returns boolean
language sql stable security definer set search_path='' as $$
 select coalesce(public.app_session_is_valid() and public.is_platform_owner(),false);
$$;
revoke all on function private.master_admin_cost_authorized() from public,anon,authenticated,service_role;

create function public.master_admin_ai_cost_companies(p_after_company_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare items jsonb;more boolean;last_id uuid;
begin
 if not private.master_admin_cost_authorized() then return jsonb_build_object('ok',false,'code','FORBIDDEN');end if;
 with rows as (select c.id,coalesce(nullif(btrim(c.display_name),''),c.id::text) name
  from public.companies c where (p_after_company_id is null or c.id>p_after_company_id)
  and exists(select 1 from private.master_ai_cycles cy where cy.company_id=c.id) order by c.id limit 51),
 shown as(select * from rows order by id limit 50)
 select (select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) from shown s),(select count(*)>50 from rows),(select id from shown order by id desc limit 1) into items,more,last_id;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('actorUserId',auth.uid(),'companies',items,'next',case when more then last_id else null end));
end;$$;

create function public.master_admin_ai_cost_cycles(p_company_id uuid,p_before_start timestamptz default null,p_before_cycle_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare items jsonb;more boolean;last_id uuid;last_start timestamptz;
begin
 if not private.master_admin_cost_authorized() then return jsonb_build_object('ok',false,'code','FORBIDDEN');end if;
 if p_company_id is null or (p_before_start is null)<>(p_before_cycle_id is null) or p_before_start is not null and not isfinite(p_before_start) then
  return jsonb_build_object('ok',false,'code','INVALID_INPUT');end if;
 with rows as (select c.id,c.starts_at,c.expires_at from private.master_ai_cycles c where c.company_id=p_company_id
  and (p_before_start is null or (c.starts_at,c.id)<(p_before_start,p_before_cycle_id)) order by c.starts_at desc,c.id desc limit 51),
 shown as(select * from rows order by starts_at desc,id desc limit 50)
 select (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'startsAt',s.starts_at,'expiresAt',s.expires_at) order by s.starts_at desc,s.id desc),'[]'::jsonb) from shown s),
 (select count(*)>50 from rows),(select id from shown order by starts_at,id limit 1),(select starts_at from shown order by starts_at,id limit 1) into items,more,last_id,last_start;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('companyId',p_company_id,'cycles',items,'next',case when more then jsonb_build_object('id',last_id,'startsAt',last_start) else null end));
end;$$;

create function public.master_admin_read_ai_cycle_costs(p_company_id uuid,p_cycle_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare c private.master_ai_cycles;r jsonb;unsettled bigint;
begin
 if not private.master_admin_cost_authorized() then return jsonb_build_object('ok',false,'code','FORBIDDEN');end if;
 select * into c from private.master_ai_cycles where company_id=p_company_id and id=p_cycle_id;
 if c.id is null then return jsonb_build_object('ok',false,'code','CYCLE_UNAVAILABLE');end if;
 r:=private.master_admin_ai_cycle_cost_aggregate(p_company_id,p_cycle_id);
 if r->>'ok'<>'true' then return r;end if;
 select count(*) into unsettled from public.ai_usage_ledger a where a.company_id=c.company_id and a.usage_mode='company_live'
  and a.created_at>=c.starts_at and a.created_at<c.expires_at and a.cost_baisa is null;
 return jsonb_build_object('ok',true,'data',(r->'data')||jsonb_build_object('companyId',c.company_id,'cycleId',c.id,'startsAt',c.starts_at,'expiresAt',c.expires_at,'unsettledAttempts',unsettled));
end;$$;
revoke all on function public.master_admin_ai_cost_companies(uuid),public.master_admin_ai_cost_cycles(uuid,timestamptz,uuid),public.master_admin_read_ai_cycle_costs(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function public.master_admin_ai_cost_companies(uuid),public.master_admin_ai_cost_cycles(uuid,timestamptz,uuid),public.master_admin_read_ai_cycle_costs(uuid,uuid) to authenticated;
notify pgrst,'reload schema';
commit;
